<?php require_once __DIR__.'/config.php';$items=$_SESSION['cart']??[];if(!$items)redirect('cart.php');$total=array_sum(array_map(fn($i)=>$i['price']*$i['quantity'],$items));if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$wa=preg_replace('/\D/','',$_POST['whatsapp']??'');$address=trim($_POST['address']??'');if(!$name||!$email||strlen($wa)<8||!$address){$error='Lengkapi data pelanggan dengan benar.';}else{try{$pdo=db();$pdo->beginTransaction();$st=$pdo->prepare('INSERT INTO customers(full_name,email,whatsapp,address) VALUES(?,?,?,?)');$st->execute([$name,$email,$wa,$address]);$cid=(int)$pdo->lastInsertId();$code='TX-'.strtoupper(bin2hex(random_bytes(4)));$pdo->prepare('INSERT INTO checkout_transactions(transaction_code,customer_id,total) VALUES(?,?,?)')->execute([$code,$cid,$total]);$tx=(int)$pdo->lastInsertId();$groups=[];foreach($items as $i){$q=$pdo->prepare('SELECT c.slug,c.name FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=?');$q->execute([$i['product_id']]);$cat=$q->fetch();$groups[$cat['slug']]['name']=$cat['name'];$groups[$cat['slug']]['items'][]=$i;} $orderIds=[];foreach($groups as $slug=>$group){$prefix=['jaket'=>'J','batik'=>'B','kaos'=>'K'][$slug]??'C';$pdo->prepare('UPDATE order_sequences SET last_number=LAST_INSERT_ID(last_number+1) WHERE category_key=?')->execute([$slug]);$num=(int)$pdo->query('SELECT LAST_INSERT_ID()')->fetchColumn();$orderNo=$prefix.str_pad((string)$num,3,'0',STR_PAD_LEFT);$sum=array_sum(array_map(fn($i)=>$i['price']*$i['quantity'],$group['items']));$pdo->prepare('INSERT INTO orders(checkout_transaction_id,order_number,category_key,customer_id,total,customer_note) VALUES(?,?,?,?,?,?)')->execute([$tx,$orderNo,$slug,$cid,$sum,trim($_POST['note']??'')]);$oid=(int)$pdo->lastInsertId();$orderIds[]=$oid;$line=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,category_name,unit_price,quantity,selected_size_code,selected_size_name,selected_variant,selected_motif) VALUES(?,?,?,?,?,?,?,?,?,?)');foreach($group['items'] as $i)$line->execute([$oid,$i['product_id'],$i['name'],$group['name'],$i['price'],$i['quantity'],$i['size_code'],$i['size_name'],$i['variant']?:null,$i['motif']?:null]);}$pdo->commit();unset($_SESSION['cart']);$_SESSION['confirmation_orders']=$orderIds;redirect('confirmation.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error='Pesanan belum dapat disimpan. Silakan coba lagi.';}}}$title='Checkout';require __DIR__.'/includes/header.php';?><main class="checkout-wrap"><div class="eyebrow">SECURE CHECKOUT</div><h1 class="serif text-5xl mt-2">Complete your order.</h1><?php if(!empty($error)):?><p class="error mt-5"><?=e($error)?></p><?php endif;?><div class="grid md:grid-cols-2 gap-10 mt-8"><form method="post" class="bg-white p-7"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><h2 class="serif text-2xl">Delivery details</h2><div class="field"><label>Nama lengkap</label><input required name="full_name" value="<?=e($_POST['full_name']??'')?>"></div><div class="field"><label>Email</label><input required type="email" name="email" value="<?=e($_POST['email']??'')?>"></div><div class="field"><label>Nomor WhatsApp</label><input required name="whatsapp" placeholder="628..." value="<?=e($_POST['whatsapp']??'')?>"></div><div class="field"><label>Alamat pengiriman</label><textarea required name="address" rows="4"><?=e($_POST['address']??'')?></textarea></div><div class="field"><label>Catatan pesanan (opsional)</label><textarea name="note" rows="2"></textarea></div><button class="btn gold w-full mt-3">PLACE ORDER</button></form><aside class="summary m-0 max-w-none"><h2 class="serif text-2xl">Order summary</h2><?php foreach($items as $i):?><div class="flex gap-3 py-4 border-b"><img class="w-14 h-16 object-cover" src="<?=e($i['image'])?>" alt=""><div class="flex-1 text-sm"><b><?=e($i['name'])?></b><p class="m-0 text-slate-500"><?=e($i['size_name'])?> · <?= $i['quantity']?> pcs</p></div><b class="text-sm"><?=money($i['price']*$i['quantity'])?></b></div><?php endforeach;?><div class="line text-lg mt-5"><strong>Total</strong><strong><?=money($total)?></strong></div></aside></div></main><?php require __DIR__.'/includes/footer.php'; ?>
